                      @if (m.retired) { (retired) }
                      @if (m.out) { (not in the pool today) }
                      <span class="visually-hidden">cut</span> <span data-testid="pool-cut">{{ m.cut | fig }}</span>
                      @for (h of cutHistory(); track h.period) {
