// pot for a pool that is a member of none, else its cut in the pool above. A member retired, or held on the day,
// counts toward the total but has no cut; a member whose dates do not include the day is left out entirely.
function shownPools(
  pools: readonly PoolView[],
  people: readonly RosterPerson[],
  sheetPot: string | null,
  today: string | null,
): ShownPool[] {
  const retired = new Map(people.map((p) => [p.id, p.retiredFrom !== null]));
  const held = new Set(
    people
      .filter((p) => today !== null && p.holds.some((h) => h.from <= today && (h.to === null || today <= h.to)))
      .map((p) => p.id),
  );
  const parent = parents(pools);
  const counted = new Map(
    pools.map((pool) => {
      const members = pool.members.map((m) => ({
        ...m,
        key: m.personId !== null ? String(m.personId) : `pool-${m.name}`,
        retired: m.personId !== null ? (retired.get(m.personId) ?? m.retired) : false,
        out: !dated(m, today),
        held: m.personId !== null && held.has(m.personId),
      }));
      const total = members.reduce((sum, m) => sum + (m.out ? 0 : hundredths(m.share)), 0);
      return [pool.id, { pool, members, total, balanced: total === 10000 }] as const;
    }),
  );
