function percent(h: number): string {
  return `${Math.floor(h / 100)}.${String(h % 100).padStart(2, '0')}`;
}

// An amount of two decimals as a whole number of cents, and back.
function cents(amount: string): bigint {
  const [whole, frac = ''] = amount.split('.');
  return BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0'));
}

function money(c: bigint): string {
  return `${c / 100n}.${String(c % 100n).padStart(2, '0')}`;
}

/**
 * Each member's cut of the pot (in cents), in member order: the pot times their share over the shares of the members
 * with a cut added up, rounded half to even to the cent; a retired member, one held on the sheet's today, and one
 * whose dates do not include it, has none (0). The remainder left by the rounding goes to the member with the smallest
 * non-zero cut (the latest added on a tie), or, with no non-zero cut, to the last member with a share, so the cuts
 * total exactly the pot; with no member left with a cut, each is 0, except that a pool whose every member is retired has no cuts at all (null).
 */
function cuts(
  pot: bigint,
  members: readonly { share: string; retired: boolean; held: boolean; out: boolean }[],
): bigint[] | null {
  if (members.length > 0 && members.every((m) => m.retired)) return null;
  const shares = members.map((m) => (m.retired || m.held || m.out ? 0n : BigInt(hundredths(m.share))));
  const of = shares.reduce((sum, h) => sum + h, 0n);
  if (of === 0n) return shares.map(() => 0n);
  const result = shares.map((h) => {
    const exact = pot * h;
    let q = exact / of;
    const r = (exact % of) * 2n;
    if (r > of || (r === of && q % 2n === 1n)) q += 1n;
    return q;
  });
  let to = -1;
  result.forEach((c, i) => {
    if (c !== 0n && (to < 0 || c <= result[to])) to = i;
  });
  if (to < 0) {
    shares.forEach((h, i) => {
      if (h > 0n) to = i;
    });
  }
  result[to] += pot - result.reduce((sum, c) => sum + c, 0n);
  return result;
}

